import {icon} from './icons.js';
import {cloud,configured,currentSession,currentUser,login,signup,logout} from './cloud.js';
import {demo,resetDemo} from './demo.js';
import {homeToday,shiftPeriod,shiftMonth,periodLabel,monthLabel,bucketLabel,sumKwh,PERIODS} from './energy.js';

const $=sel=>document.querySelector(sel);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>Number(x)||0;
const num=(x,dec=1)=>n(x).toLocaleString('en-US',{maximumFractionDigits:dec,minimumFractionDigits:dec});
const baht=x=>'฿'+n(x).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const labelType={energy_meter:'มิเตอร์หลัก',smart_switch:'สวิตช์อัจฉริยะ',energy_switch:'สวิตช์อัจฉริยะ (เดิม)',sensor:'เซนเซอร์'};
const iconType={energy_meter:'bolt',smart_switch:'bulb',energy_switch:'plug',sensor:'thermometer'};
const smartIcon=d=>{const x=(d.name||'').toLowerCase();if(d.kind==='energy_meter')return 'bolt';if(/air|แอร์|ac |conditioner/.test(x))return 'snowflake';if(/fan|พัดลม/.test(x))return 'fan';if(/curtain|ม่าน/.test(x))return 'curtain';if(/plug|socket|ปลั๊ก/.test(x))return 'plug';if(/tv|ทีวี/.test(x))return 'monitor';return iconType[d.kind]||'cpu'};
const pageLabels={overview:'ภาพรวมบ้าน',devices:'อุปกรณ์ของฉัน',energy:'พลังงานไฟฟ้า',rooms:'ห้องภายในบ้าน',automations:'ระบบอัตโนมัติ',members:'สมาชิก',notifications:'การแจ้งเตือน',settings:'ตั้งค่า',detail:'รายละเอียดอุปกรณ์'};
const state={roomFilter:'all',deviceSearch:'',ready:false,user:null,demo:false,authMode:'login',page:'overview',homes:[],homeId:null,rooms:[],devices:[],automations:[],members:[],notifications:[],commands:[],dashboard:null,history:[],detailId:null,modal:null,busy:false,energyPeriod:'week',energyAnchor:homeToday(),energySeries:[],energySeriesKey:'',billMonth:homeToday().slice(0,7),billSeries:[],billSeriesKey:'',trendError:''};
const api=()=>state.demo?demo:cloud;
const home=()=>state.homes.find(h=>h.id===state.homeId);
const dev=id=>state.devices.find(d=>d.id===id);
const roomName=id=>state.rooms.find(r=>r.id===id)?.name||'ไม่ระบุห้อง';
const isOnline=d=>Boolean(d?.last_seen&&Date.now()-new Date(d.last_seen).getTime()<90000);
const isOwner=()=>state.demo||state.members.find(m=>m.user_id===state.user?.id)?.role==='owner';
const canManage=()=>state.demo||['owner','admin'].includes(state.members.find(m=>m.user_id===state.user?.id)?.role);
const canOperate=()=>state.demo||['owner','admin','member'].includes(state.members.find(m=>m.user_id===state.user?.id)?.role);
const showToast=(message,error=false)=>{let el=$('#toasts');if(!el)return;const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;el.appendChild(node);setTimeout(()=>node.remove(),4600)};
const empty=(title,desc,ic='info')=>`<div class="empty">${icon(ic,34)}<strong>${safe(title)}</strong><span class="small">${safe(desc)}</span></div>`;
const btn=(title,act,ic='plus',cls='')=>`<button type="button" class="btn ${cls}" data-act="${act}">${icon(ic,16)} ${safe(title)}</button>`;
const mainMeter=()=>state.devices.find(d=>d.id===state.dashboard?.billing_meter_id&&d.kind==='energy_meter')||state.devices.find(d=>d.kind==='energy_meter')||null;
const measured=(value,dec=1)=>value===null||value===undefined?'—':num(value,dec);
const pending=id=>state.commands.find(c=>c.device_id===id&&c.status==='pending'&&Date.now()-new Date(c.created_at).getTime()<120000);
function displayDay(v){
 const t=String(v||'');
 const th=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
 const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 const m=t.match(/^(\d{4})-(\d{2})-(\d{2})$/);
 if(m)return `${Number(m[3])} ${th[Number(m[2])-1]||''}`;
 const d=t.match(/^(\d{1,2})\s+([A-Za-z]{3})$/);
 if(d)return `${Number(d[1])} ${th[months.indexOf(d[2])]||d[2]}`;
 return t;
}
function miniChart(values,width=750,height=242,type='bar',labels=[]){
 const arr=(values||[]).map(x=>Math.max(0,n(x)));
 if(!arr.length)return empty('ยังไม่มีข้อมูลกราฟ','รอรับข้อมูลจากมิเตอร์หลัก','chart');
 if(type==='bar'){
  const peak=Math.max(...arr,1);
  const ceil=Math.max(1,Math.ceil(peak/4)*4);
  const ticks=Array.from({length:5},(_,i)=>num(ceil*(4-i)/4,ceil<5?1:0));
  const cols=arr.map((v,i)=>{
   const day=displayDay(labels[i]||String(i+1));
   const value=num(v,2);
   const ratio=Math.min(100,Math.max(0,v/ceil*100));
   return `<div class="usage-bar-col" title="${safe(day)} · ${value} kWh"><div class="usage-bar-track"><div class="usage-bar" style="height:${ratio}%"><span class="usage-bar-value">${value}</span></div></div><span class="usage-day">${safe(day)}</span></div>`;
  }).join('');
  return `<div class="usage-bar-chart" role="img" aria-label="กราฟการใช้ไฟฟ้ารายวัน หน่วยกิโลวัตต์ชั่วโมง"><div class="usage-y-axis">${ticks.map(t=>`<span>${t}</span>`).join('')}</div><div class="usage-chart-field"><div class="usage-grid-lines">${ticks.map(()=>'<span></span>').join('')}</div><div class="usage-bar-columns" style="--usage-count:${arr.length}">${cols}</div></div></div>`;
 }
 const max=Math.max(...arr,1)*1.15,left=49,right=12,top=17,bottom=36,plotW=width-left-right,plotH=height-top-bottom,base=top+plotH;
 const grid=[0,1,2,3].map(i=>{const y=base-i*plotH/3;return `<line x1="${left}" x2="${width-right}" y1="${y}" y2="${y}" stroke="#e6edf8" stroke-dasharray="4 6"/><text x="${left-10}" y="${y+4}" text-anchor="end" fill="#99aac1" font-size="12">${num(max*i/3,0)}</text>`}).join('');
 const a=arr.map((v,i)=>[left+(i+.5)*plotW/arr.length,base-v/max*plotH]);
 const points=a.map(([x,y])=>`${x},${y}`).join(' ');
 const marks=`<polygon points="${a[0][0]},${base} ${points} ${a[a.length-1][0]},${base}" fill="url(#area2)"/><polyline points="${points}" fill="none" stroke="#387cf5" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`+a.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.4" fill="#387cf5" stroke="white" stroke-width="1.5"/>`).join('');
 const xLabels=arr.map((v,i)=>`<text x="${left+(i+.5)*plotW/arr.length}" y="${height-10}" text-anchor="middle" fill="#8ea1bc" font-size="11">${safe(labels[i]||String(i+1))}</text>`).join('');
 return `<svg class="energy-svg" preserveAspectRatio="xMidYMid meet" viewBox="0 0 ${width} ${height}" role="img" aria-label="กราฟข้อมูลกำลังไฟฟ้า"><defs><linearGradient id="area2" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#5595ff" stop-opacity=".25"/><stop offset="1" stop-color="#5595ff" stop-opacity="0"/></linearGradient></defs>${grid}${marks}${xLabels}</svg>`;
}

const todayAtHome=()=>homeToday(home()?.timezone||'Asia/Bangkok');
function seriesKey(period,anchor){return [state.homeId,period,anchor].join('|')}
async function loadTrends(force=false){
 if(!state.homeId||!['energy','detail'].includes(state.page))return;
 if(state.page==='detail'&&dev(state.detailId)?.kind!=='energy_meter')return;
 const key=seriesKey(state.energyPeriod,state.energyAnchor),billKey=seriesKey('month',state.billMonth+'-01');
 const jobs=[];
 if(force||state.energySeriesKey!==key)jobs.push(api().getEnergySeries(state.homeId,state.energyPeriod,state.energyAnchor).then(rows=>{if(seriesKey(state.energyPeriod,state.energyAnchor)===key){state.energySeries=rows;state.energySeriesKey=key}}));
 if(state.page==='energy'&&(force||state.billSeriesKey!==billKey))jobs.push(api().getEnergySeries(state.homeId,'month',state.billMonth+'-01').then(rows=>{if(seriesKey('month',state.billMonth+'-01')===billKey){state.billSeries=rows;state.billSeriesKey=billKey}}));
 if(!jobs.length)return;
 try{await Promise.all(jobs);state.trendError=''}catch(e){state.trendError=e.message||String(e)}
}
function periodControls(){
 const period=state.energyPeriod;
 const limits={day:'รายวัน',week:'รายสัปดาห์',month:'รายเดือน',year:'รายปี'};
 let select='';
 if(period==='month')select=`<input class="history-date-input" aria-label="เลือกเดือนของกราฟ" data-energy-month type="month" value="${safe(state.energyAnchor.slice(0,7))}">`;
 else if(period==='year')select=`<select class="history-date-input" aria-label="เลือกปีของกราฟ" data-energy-year>${Array.from({length:8},(_,i)=>Number(todayAtHome().slice(0,4))+1-i).map(year=>`<option value="${year}" ${year===Number(state.energyAnchor.slice(0,4))?'selected':''}>${year+543}</option>`).join('')}</select>`;
 else select=`<input class="history-date-input" aria-label="เลือกวันที่ของกราฟ" data-energy-date type="date" value="${safe(state.energyAnchor)}">`;
 return `<div class="history-controls"><div class="history-tabs" role="group" aria-label="ช่วงเวลาของกราฟ">${PERIODS.map(x=>`<button type="button" data-act="energy-period" data-id="${x}" class="${period===x?'selected':''}" aria-pressed="${period===x}">${limits[x]}</button>`).join('')}</div><div class="history-date-controls"><button class="history-step" data-act="energy-prev" aria-label="ช่วงก่อนหน้า">${icon('chevron',14)}</button>${select}<button class="history-step next" data-act="energy-next" aria-label="ช่วงถัดไป">${icon('chevron',14)}</button></div></div>`;
}
function trendChart(rows,kind='energy'){
 if(!rows?.length)return empty('ไม่มีข้อมูลในช่วงที่เลือก','โปรดเลือกช่วงเวลาอื่นหรือรอข้อมูลจากมิเตอร์','chart');
 const isPower=kind==='power';
 const period=state.energyPeriod;
 const vals=rows.map(r=>isPower?(r.avg_power_w==null?null:Number(r.avg_power_w)):Number(r.kwh)||0);
 const max=Math.max(1,...vals.filter(x=>x!=null));
 const safeMax=max<=10?Math.ceil(max*1.2*2)/2:Math.ceil(max*1.15/10)*10;
 const step=period==='day'?3:period==='month'?5:period==='year'?1:1;
 const units=isPower?'W':'kWh';
 const ticks=Array.from({length:5},(_,i)=>num(safeMax*(4-i)/4,safeMax<=10?1:0));
 if(!isPower){
  return `<div class="history-chart" role="img" aria-label="กราฟการใช้พลังงาน ${periodLabel(period,state.energyAnchor)}"><div class="history-axis">${ticks.map(t=>`<span>${t}</span>`).join('')}</div><div class="history-field"><div class="history-lines">${ticks.map(()=>'<span></span>').join('')}</div><div class="history-columns" style="--bar-count:${rows.length}">${rows.map((r,i)=>{const value=Number(r.kwh)||0;const label=bucketLabel(period,r.bucket);const pct=Math.max(0,Math.min(100,value/safeMax*100));const shown=(period!=='month'||i%step===0||i===rows.length-1);return `<div class="history-column" title="${safe(label)}: ${num(value,3)} kWh"><div class="history-track"><div class="history-bar" style="height:${pct}%"></div></div><span class="history-x-label">${shown?safe(label):''}</span></div>`}).join('')}</div></div></div>`;
 }
 // Power readings: clean axis with at most 7 labels regardless of the number of samples.
 const width=920,height=275,left=58,right=12,top=16,bottom=39,plotW=width-left-right,plotH=height-top-bottom,base=height-bottom;
 const pts=vals.map((v,i)=>v===null?null:{x:left+(i+.5)*plotW/vals.length,y:base-v/safeMax*plotH,v,i});
 let segments=[],current=[];
 for(const pt of pts){if(pt)current.push(pt);else if(current.length){segments.push(current);current=[]}}if(current.length)segments.push(current);
 const xEvery=Math.max(1,Math.ceil(vals.length/7));
 const lines=segments.map(seg=>{const path=seg.map((pt,i)=>`${i?'L':'M'} ${pt.x.toFixed(1)} ${pt.y.toFixed(1)}`).join(' ');return `<path d="${path}" fill="none" stroke="#367af5" stroke-width="3.3" stroke-linejoin="round" stroke-linecap="round"/>`}).join('');
 const dots=pts.filter(x=>x).map(pt=>`<circle cx="${pt.x}" cy="${pt.y}" r="3.8" fill="#367af5" stroke="white" stroke-width="1.5"><title>${safe(bucketLabel(period,rows[pt.i].bucket))}: ${num(pt.v,1)} W (เฉลี่ย)</title></circle>`).join('');
 const grid=Array.from({length:5},(_,i)=>{const y=top+(plotH*i/4);return `<line x1="${left}" x2="${width-right}" y1="${y}" y2="${y}" stroke="#e6eef9" stroke-dasharray="4 6"/><text x="${left-10}" y="${y+5}" text-anchor="end" fill="#8295ae" font-size="12">${num(safeMax*(4-i)/4,0)}</text>`}).join('');
 const labels=rows.map((row,i)=>i%xEvery===0||i===rows.length-1?`<text x="${left+(i+.5)*plotW/vals.length}" y="${height-11}" text-anchor="middle" fill="#8097b7" font-size="12">${safe(bucketLabel(period,row.bucket))}</text>`:'').join('');
 return `<svg class="energy-svg energy-power-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="กราฟกำลังไฟเฉลี่ย (${units})"><defs><linearGradient id="trendFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#6b9eff" stop-opacity=".22"/><stop offset="1" stop-color="#6b9eff" stop-opacity=".01"/></linearGradient></defs>${grid}${segments.map(seg=>`<polygon points="${seg[0].x},${base} ${seg.map(p=>p.x+','+p.y).join(' ')} ${seg[seg.length-1].x},${base}" fill="url(#trendFill)"/>`).join('')}${lines}${dots}${labels}</svg>`;
}
function selectedCost(){const sum=sumKwh(state.billSeries),h=home();return {kwh:sum,cost:sum*n(h?.rate_per_kwh)+(n(h?.service_fee))}}
function billingHistory(){const bill=selectedCost(),m=mainMeter();return `<div class="panel bill-history section-space"><div class="panel-head bill-head"><div class="head-with-icon"><span class="panel-icon">${icon('calendar',20)}</span><div><h3>ประวัติค่าไฟรายเดือน</h3><p>เลือกเดือนเพื่อดูยอดพลังงานจากมิเตอร์ตู้เมน</p></div></div><div class="billing-switch"><button class="history-step" data-act="bill-prev" aria-label="เดือนก่อนหน้า">${icon('chevron',14)}</button><input type="month" data-bill-month aria-label="เลือกเดือนค่าไฟ" value="${safe(state.billMonth)}"><button class="history-step next" data-act="bill-next" aria-label="เดือนถัดไป">${icon('chevron',14)}</button></div></div><div class="bill-result"><div><span>เดือนที่เลือก</span><strong>${safe(monthLabel(state.billMonth))}</strong></div><div><span>ใช้พลังงาน</span><strong>${m?num(bill.kwh,2):'—'} <small>kWh</small></strong></div><div><span>ค่าไฟประมาณการ</span><strong>${m?baht(bill.cost):'—'}</strong></div></div><div class="muted small bill-disclaimer">คำนวณจากพลังงานที่บันทึกจริงในเดือนนั้น × อัตราค่าไฟที่ตั้งไว้ปัจจุบัน + ค่าบริการ (ยังไม่รวมรายละเอียดอัตราขั้นบันได, Ft หรือ VAT)</div></div>`}
function historicalPanel(kind='energy'){
 const power=kind==='power',name=power?'กำลังไฟเฉลี่ยย้อนหลัง':'ประวัติการใช้ไฟฟ้า';
 const title=periodLabel(state.energyPeriod,state.energyAnchor);
 const series=state.energySeries||[];
 return `<div class="panel usage-panel trend-panel"><div class="panel-head trend-heading"><div class="head-with-icon"><span class="panel-icon">${icon('chart',19)}</span><div><h3>${name}</h3><p>${safe(title)} · ${power?'กำลังไฟเฉลี่ยตามช่วง (W)':'ปริมาณพลังงาน (kWh)'}</p></div></div><span class="tag">${power?'W':'kWh'}</span></div>${periodControls()}${state.trendError?`<div class="alert-box">โหลดข้อมูลย้อนหลังไม่สำเร็จ: ${safe(state.trendError)} · ตรวจว่าติดตั้ง Migration v2.4 แล้ว</div>`:''}<div class="chart-wrap trend-wrap">${series.length?trendChart(series,kind):empty('ยังไม่มีข้อมูล','เลือกระยะเวลาหรือรอให้มิเตอร์เริ่มบันทึกข้อมูล')}</div><div class="trend-summary"><span>${power?'กราฟแสดงค่าเฉลี่ย ไม่ใช่ค่ากำลังไฟทุกวินาที':'รวมช่วงที่เลือก'} </span><strong>${power?'อ่านค่าจากมิเตอร์หลัก':num(sumKwh(series),2)+' kWh'}</strong>${state.demo?'<span class="tag">ข้อมูลจำลอง</span>':''}</div></div>`;
}
const stat=(title,value,unit,ic,tone,foot)=>`<div class="stat-card"><div class="stat-top"><span class="stat-symbol ${tone}">${icon(ic,20)}</span><span class="stat-tinyline"></span></div><div class="stat-title">${title}</div><div class="stat-value">${value} <span>${unit}</span></div><div class="stat-foot">${foot}</div></div>`;
function renderOverview(){
 const d=state.dashboard||{},m=mainMeter(),active=Boolean(m&&isOnline(m)),history=d.history||[];
 const h=home(),who=(h?.name||'บ้านของฉัน');const match=state.roomFilter==='all'?state.devices.filter(x=>x.kind!=='energy_meter'):state.devices.filter(x=>x.kind!=='energy_meter'&&x.room_id===state.roomFilter);
 const roomPills=[`<button class="room-chip ${state.roomFilter==='all'?'selected':''}" data-act="room-filter" data-id="all">ทุกอุปกรณ์</button>`,...state.rooms.map(r=>`<button class="room-chip ${state.roomFilter===r.id?'selected':''}" data-act="room-filter" data-id="${safe(r.id)}">${safe(r.name)}</button>`)].join('');
 const morning=new Date().getHours()<12?'สวัสดีตอนเช้า':new Date().getHours()<18?'สวัสดีตอนบ่าย':'สวัสดีตอนเย็น';
 return `<section class="welcome-banner"><div class="welcome-copy"><span class="eyebrow">บ้านอัจฉริยะของคุณ · ${safe(who)}</span><h2>${morning}</h2><p>ภาพรวมและการใช้งานบ้านอัจฉริยะของคุณวันนี้</p><div class="welcome-status">${icon('shield',16)} ${state.demo?'กำลังดูข้อมูลตัวอย่าง':'ควบคุมผ่านคลาวด์ส่วนตัว'} <span>·</span> ${state.devices.filter(isOnline).length} อุปกรณ์ออนไลน์</div></div><div class="home-art" aria-hidden="true"><svg viewBox="0 0 400 192" fill="none"><path d="M20 167h360" stroke="#c8def8" stroke-width="2"/><path d="m104 83 104-68 115 68v86H104z" fill="#e6f1ff" stroke="#abc9ed" stroke-width="3"/><path d="m88 91 119-80 132 80" stroke="#82ace6" stroke-width="10" stroke-linejoin="round"/><path d="M131 99h57v47h-57zM232 99h57v47h-57z" fill="#b5d8ff"/><path d="M202 118h32v51h-32z" fill="#8cb8ee"/><path d="M119 84h179" stroke="#c6dbf6" stroke-width="3"/><circle cx="57" cy="110" r="34" fill="#b9e3cf"/><rect x="54" y="113" width="7" height="59" rx="3" fill="#9bc9ae"/><circle cx="349" cy="114" r="28" fill="#b9e3cf"/><path d="M347 123v50" stroke="#9bc9ae" stroke-width="6"/><path d="M80 169h270" stroke="#99bfe7" stroke-width="6" stroke-linecap="round"/></svg></div></section>
 <div class="dash-section-heading"><div><h3>ภาพรวมการใช้ไฟฟ้า</h3><p>วัดไฟรวมทั้งบ้านจากมิเตอร์ที่ตู้เมนเพียงจุดเดียว</p></div><button class="text-link" data-page="energy">ดูกราฟทั้งหมด ${icon('arrow',16)}</button></div>
 <div class="stats">${stat('กำลังไฟขณะนี้',active?measured(m.last_power_w,0):'—','W','bolt','',active?'มิเตอร์ออนไลน์':'กำลังรอข้อมูลสด')} ${stat('ใช้ไฟวันนี้',m?num(d.today_kwh,2):'—','kWh','chart','blue','ข้อมูลจากมิเตอร์ตู้เมน')}${stat('เดือนนี้',m?num(d.month_kwh,2):'—','kWh','calendar','purple','พลังงานที่ใช้ในเดือนนี้')}${stat('ค่าไฟประมาณการ',m?baht(d.estimate_cost):'—','','wallet','gold','คำนวณจากอัตราค่าไฟที่ตั้งไว้')}</div>
 <div class="panel usage-panel"><div class="panel-head"><div class="head-with-icon"><span class="panel-icon">${icon('chart',19)}</span><div><h3>กราฟการใช้ไฟฟ้า</h3><p>ย้อนหลัง 7 วัน · มิเตอร์ตู้เมน</p></div></div><button class="text-link" data-page="energy">รายละเอียดพลังงาน ${icon('chevron',15)}</button></div><div class="chart-wrap">${m?miniChart(history.map(h=>h.kwh),750,242,'bar',history.map(h=>h.day)):empty('ยังไม่ได้เชื่อมต่อมิเตอร์หลัก','เพิ่ม ESP32-C6 เพื่อเริ่มวัดการใช้ไฟ','bolt')}</div></div>
 <div class="panel readings-panel"><div class="panel-head"><div class="head-with-icon"><span class="panel-icon">${icon('activity',19)}</span><div><h3>ค่าที่วัดจากตู้เมน</h3><p>ESP32-C6 · PZEM-004T · อ่านค่าอย่างเดียว</p></div></div>${m?deviceStatus(m):'<span class="tag">ยังไม่ได้จับคู่</span>'}</div><div class="reading-grid"><div><span class="reading-ic mint">${icon('bolt',19)}</span><div><small>แรงดันไฟฟ้า</small><b>${active?measured(m.last_voltage_v):'—'} <em>V</em></b></div></div><div><span class="reading-ic sky">${icon('activity',19)}</span><div><small>กระแสไฟฟ้า</small><b>${active?measured(m.last_current_a,2):'—'} <em>A</em></b></div></div><div><span class="reading-ic lilac">${icon('chart',19)}</span><div><small>ตัวประกอบกำลัง</small><b>${active?measured(m.last_pf,2):'—'}</b></div></div><div><span class="reading-ic sky">${icon('clock',19)}</span><div><small>ความถี่</small><b>${active?measured(m.last_frequency_hz):'—'} <em>Hz</em></b></div></div></div></div>
 <div class="dash-section-heading device-heading"><div><h3>อุปกรณ์ของฉัน</h3><p>ควบคุมอุปกรณ์ในบ้านได้จากทุกที่</p></div><button class="text-link" data-page="devices">ดูทั้งหมด ${icon('arrow',16)}</button></div><div class="room-chips">${roomPills}</div>${renderDevicesGrid(match.slice(0,6))}<div class="add-card"><div class="stat-symbol blue">${icon('plus',18)}</div><div><strong>เพิ่มอุปกรณ์ให้บ้านอัจฉริยะ</strong><small>เพิ่มสวิตช์ เซนเซอร์ หรือมิเตอร์ ESP32 ผ่านขั้นตอนตั้งค่า Wi-Fi ที่ง่ายขึ้น</small></div>${canManage()?btn('เพิ่มอุปกรณ์','add-device','plus'):''}</div>`;
}
function deviceStatus(d){const p=pending(d.id);return p?`<span class="status wait"><span class="s-dot"></span>กำลังดำเนินการ</span>`:isOnline(d)?`<span class="status"><span class="s-dot"></span>ออนไลน์</span>`:`<span class="status off"><span class="s-dot"></span>ออฟไลน์</span>`}
function renderDevicesGrid(devices){return devices.length?`<div class="device-grid">${devices.map(d=>{const ico=smartIcon(d);const label=d.kind==='energy_meter'?'มิเตอร์วัดไฟทั้งบ้าน':d.kind==='sensor'?'เซนเซอร์อ่านค่า':d.relay_state?'เปิดอยู่':'ปิดอยู่';return `<article class="device-card" data-search-name="${safe((d.name+' '+roomName(d.room_id)).toLowerCase())}"><div class="device-head"><span class="device-icon ${ico} ${d.kind==='sensor'?'sensor':d.control_enabled?'switch':''}">${icon(ico,25)}</span>${d.control_enabled?`<button class="switch-toggle ${d.relay_state?'on':''}" type="button" role="switch" aria-checked="${Boolean(d.relay_state)}" aria-label="${d.relay_state?'ปิด':'เปิด'} ${safe(d.name)}" data-act="switch" data-id="${safe(d.id)}" ${!isOnline(d)||!canOperate()||pending(d.id)?'disabled':''}></button>`:deviceStatus(d)}</div><div class="device-name">${safe(d.name)}</div><div class="device-room">${d.kind==='energy_meter'?'ตู้เมน':safe(roomName(d.room_id))}</div><div class="device-bottom"><div class="device-description"><span class="muted small">${pending(d.id)?'กำลังรอยืนยันคำสั่ง…':!isOnline(d)?'ออฟไลน์':label}</span></div><button type="button" class="tile-arrow" title="รายละเอียดอุปกรณ์" aria-label="รายละเอียดของ ${safe(d.name)}" data-act="detail" data-id="${safe(d.id)}">${icon('chevron',19)}</button></div></article>`}).join('')}</div>`:empty('ไม่มีอุปกรณ์ในห้องนี้','เลือกห้องอื่น หรือเพิ่มอุปกรณ์ตัวแรกของคุณ','cpu')}
function renderDevices(){return `<div class="headline-row"><div><h2>อุปกรณ์ของฉัน <span class="muted small">(${state.devices.length})</span></h2><p>มิเตอร์หลัก ที่ตู้เมน 1 ตัวต่อบ้าน + สวิตช์อัจฉริยะ และเซนเซอร์</p></div>${canManage()?btn('เพิ่มอุปกรณ์','add-device','plus'):''}</div>${renderDevicesGrid(state.devices)}<div class="panel section-space"><div class="panel-head"><h3>วิธีเพิ่มอุปกรณ์ผ่าน Wi-Fi</h3>${icon('shield',19)}</div><div class="helper-box">1. Click <b>เพิ่มอุปกรณ์</b> to open the step-by-step setup wizard.<br>2. เชื่อมต่อ Wi-Fi ชั่วคราวของ ESP32 แล้วเปิด <b>192.168.4.1</b>.<br>3. เลือก Wi-Fi บ้านในหน้าตั้งค่าบอร์ด แล้วกรอกรหัสผ่านพร้อมรหัสอนุญาตติดตั้ง<br>4. กลับหน้า Home Thames ใส่รหัสจับคู่ใช้ครั้งเดียว แล้วเลือกห้อง</div></div>`}
function renderRooms(){let rooms=state.rooms;return `<div class="headline-row"><div><h2>ห้องและพื้นที่</h2><p>จัดกลุ่มอุปกรณ์ตามห้องหรือพื้นที่</p></div>${canManage()?btn('เพิ่มห้อง','new-room','plus'):''}</div><div class="device-grid">${rooms.map(r=>`<div class="panel"><div class="panel-head"><span class="room-icon">${icon('house',20)}</span>${canManage()?`<button class="btn-ghost" data-act="remove-room" data-id="${safe(r.id)}" title="ลบห้อง">${icon('trash',16)}</button>`:''}</div><h3 style="font-size:18px;margin:14px 0 5px">${safe(r.name)}</h3><span class="muted small">${state.devices.filter(d=>d.room_id===r.id).length} อุปกรณ์เชื่อมต่อ</span></div>`).join('')}</div>${!rooms.length?empty('ยังไม่มีห้อง','เพิ่มห้องเพื่อจัดอุปกรณ์ภายในบ้าน','house'):''}`}
function renderEnergy(){const d=state.dashboard||{},m=mainMeter(),active=Boolean(m&&isOnline(m)),history=d.history||[];return `<div class="headline-row"><div><h2>วิเคราะห์การใช้ไฟ</h2><p>ข้อมูลการใช้ไฟรวมทั้งบ้านจากมิเตอร์หลักที่ตู้ไฟเท่านั้น</p></div>${canManage()?btn('ตั้งค่าค่าไฟ','settings-billing','settings','alt'):''}</div><div class="panel meter-identity"><span class="device-icon">${icon('bolt',24)}</span><div><strong>${m?safe(m.name):'มิเตอร์ไฟฟ้าหลัก'}</strong><small>${m?deviceStatus(m):'ยังไม่ได้จับคู่ · เพิ่ม ESP32-C6 + PZEM-004T'}</small></div>${m?`<button class="btn outline" data-act="detail" data-id="${safe(m.id)}">รายละเอียด ${icon('chevron',16)}</button>`:canManage()?btn('จับคู่มิเตอร์','add-device','plus'):''}</div><div class="stats">${stat('กำลังไฟขณะนี้',active?measured(m.last_power_w,0):'—','W','bolt','','ค่าจริงจากตู้เมน')}${stat('ใช้ไฟวันนี้',m?num(d.today_kwh,2):'—','kWh','chart','blue','นับตั้งแต่เที่ยงคืน')}${stat('เดือนนี้',m?num(d.month_kwh,2):'—','kWh','calendar','purple','พลังงานที่ใช้ในรอบบิล')}${stat('ค่าไฟประมาณการ',m?baht(d.estimate_cost):'—','','wallet','gold','ตั้งค่าอัตราค่าไฟในเมนูตั้งค่า')}</div>${historicalPanel('energy')}${billingHistory()}<div class="panel readings-panel section-space"><div class="panel-head"><h3>ค่าที่วัดจากตู้เมน</h3>${m?deviceStatus(m):'<span class="tag">ยังไม่ได้จับคู่</span>'}</div><div class="reading-grid"><div><span class="reading-ic mint">${icon('bolt',19)}</span><div><small>แรงดันไฟฟ้า</small><b>${active?measured(m.last_voltage_v):'—'} <em>V</em></b></div></div><div><span class="reading-ic sky">${icon('activity',19)}</span><div><small>กระแสไฟฟ้า</small><b>${active?measured(m.last_current_a,2):'—'} <em>A</em></b></div></div><div><span class="reading-ic lilac">${icon('chart',19)}</span><div><small>ตัวประกอบกำลัง</small><b>${active?measured(m.last_pf,2):'—'}</b></div></div><div><span class="reading-ic gold">${icon('clock',19)}</span><div><small>ความถี่</small><b>${active?measured(m.last_frequency_hz):'—'} <em>Hz</em></b></div></div></div></div><div class="alert-box section-space">ระบบนี้ใช้ตรวจวัดไฟฟ้าเท่านั้น ค่าไฟคำนวณจากมิเตอร์หลักเพียงจุดเดียวต่อบ้าน ไม่รวมค่าจากสวิตช์ซ้ำ และเป็นเพียงค่าประมาณ ไม่ใช่ใบแจ้งหนี้จริง</div>`}
function renderAutomations(){return `<div class="headline-row"><div><h2>ระบบอัตโนมัติ</h2><p>กำหนดเงื่อนไขให้บ้านทำงานอัตโนมัติ</p></div>${canOperate()?btn('สร้างกฎ','new-rule','plus'):''}</div><div class="list-rows">${state.automations.map(a=>`<div class="row-item"><div style="display:flex;align-items:center;gap:12px"><div class="device-icon">${icon(a.trigger_type==='daily_time'?'clock':'bolt',22)}</div><div><strong>${safe(a.name)}</strong><small>${safe(ruleDesc(a))} → ${safe(dev(a.target_device_id)?.name||'ไม่ทราบข้อมูล')} · ${a.desired_state?'ON':'OFF'}</small></div></div><div class="device-actions"><span class="tag ${a.enabled?'success':''}">${a.enabled?'เปิดใช้งาน':'หยุดชั่วคราว'}</span>${canOperate()?`<button class="btn-ghost" data-act="toggle-rule" data-id="${safe(a.id)}" title="${a.enabled?'หยุดชั่วคราว':'เปิดใช้งาน'}">${icon('power',18)}</button><button class="btn-ghost" data-act="remove-rule" data-id="${safe(a.id)}" title="ลบ">${icon('trash',17)}</button>`:''}</div></div>`).join('')||empty('ยังไม่มีกฎอัตโนมัติ','สร้างกฎอัตโนมัติแรกของคุณ','clock')}</div><div class="helper-box section-space">Automation จะทำงานบน Cloud เมื่อเปิด Scheduled Edge Function ให้เรียก <b>run-automations</b> ทุก 1 นาที การสั่งงานที่เกี่ยวกับไฟบ้านต้องผ่านฮาร์ดแวร์ป้องกันที่เหมาะสม</div>`}
function ruleDesc(a){if(a.trigger_type==='daily_time')return `ทุกวันเวลา ${String(a.time_local||'').slice(0,5)}`;if(a.trigger_type==='offline')return `${dev(a.trigger_device_id)?.name||'อุปกรณ์'} หลุดการเชื่อมต่อ`;return `${dev(a.trigger_device_id)?.name||'อุปกรณ์'} กำลังไฟ ${a.trigger_type==='power_above'?'>':'<'} ${a.threshold_w} W`}
function renderMembers(){return `<div class="headline-row"><div><h2>สมาชิกในบ้าน</h2><p>สิทธิ์การดูและควบคุมอุปกรณ์ในบ้านนี้</p></div>${canManage()?btn('เชิญสมาชิก','new-invite','plus'):''}</div><div class="panel"><div class="list-rows">${state.members.map(m=>`<div class="row-item"><div style="display:flex;align-items:center;gap:12px"><span class="pill-avatar">${safe(String(m.user_id).slice(0,2).toUpperCase())}</span><div><strong>${m.user_id===state.user?.id?'คุณ':safe(String(m.user_id).slice(0,8)+'…')}</strong><small>${safe(String(m.user_id))}</small></div></div><span style="display:flex;align-items:center;gap:7px"><span class="tag ${m.role==='owner'?'success':''}">${safe(m.role)}</span>${isOwner()&&m.role!=='owner'?`<button class="btn-ghost" data-act="remove-member" data-id="${safe(m.user_id)}" title="นำสมาชิกออก">${icon('trash',16)}</button>`:''}</span></div>`).join('')}</div></div><div class="helper-box section-space"><b>เจ้าของ / ผู้ดูแล</b> จัดการอุปกรณ์และเชิญสมาชิก · <b>สมาชิก</b> สั่งงานและสร้าง Automation · <b>ผู้ชม</b> ดูข้อมูลอย่างเดียว<br>คำเชิญเป็นลิงก์รหัสครั้งเดียว มีอายุ 24 ชั่วโมง</div>`}
function renderNotifications(){return `<div class="headline-row"><div><h2>การแจ้งเตือน</h2><p>แจ้งเตือนจาก Cloud และ Automation</p></div></div><div class="list-rows">${state.notifications.map(a=>`<div class="row-item"><div style="display:flex;gap:12px;align-items:center"><div class="device-icon">${icon('bell',20)}</div><div><strong>${safe(a.title)}</strong><small>${safe(a.message)} · ${new Date(a.created_at).toLocaleString('th-TH')}</small></div></div>${!a.read?`<button class="btn small-btn alt" data-act="read-note" data-id="${safe(a.id)}">อ่านแล้ว</button>`:'<span class="muted small">อ่านแล้ว</span>'}</div>`).join('')||empty('ไม่มีการแจ้งเตือนค้าง','ขณะนี้ยังไม่มีการแจ้งเตือน','bell')}</div>`}
function renderSettings(){let h=home();return `<div class="headline-row"><div><h2>การตั้งค่าบ้าน</h2><p>ปรับแต่งบ้านและรูปแบบการคิดค่าไฟ</p></div></div><div class="two-cols"><div class="panel"><div class="panel-head"><h3>${icon('settings',17)} &nbsp; ข้อมูลบ้าน</h3></div><div class="list-rows"><div class="row-item"><div><strong>ชื่อบ้าน</strong><small>${safe(h?.name||'')}</small></div></div><div class="row-item"><div><strong>เขตเวลา</strong><small>${safe(h?.timezone||'Asia/Bangkok')}</small></div></div><div class="row-item"><div><strong>อัตราค่าไฟต่อหน่วย</strong><small>${baht(h?.rate_per_kwh)} / หน่วย</small></div></div><div class="row-item"><div><strong>ค่าบริการรายเดือน</strong><small>${baht(h?.service_fee)}</small></div></div></div>${canManage()?`<div style="margin-top:18px">${btn('แก้ไขการตั้งค่า','settings-billing','edit','alt')}</div>`:''}</div><div class="panel"><div class="panel-head"><h3>${icon('shield',17)} &nbsp; ความปลอดภัย</h3></div><p class="muted" style="line-height:1.9">ข้อมูลแยกตามบ้านด้วย Row Level ความปลอดภัย และ ESP32 แต่ละตัวมี อุปกรณ์ Token แยกต่างหาก คำสั่งควบคุมต้องผ่านสิทธิ์สมาชิก</p><div class="helper-box">${state.demo?'โหมด Demo นี้บันทึกข้อมูลจำลองในเบราว์เซอร์ของคุณเท่านั้น':'โหมดคลาวด์ · เชื่อมต่อ Supabase แบบยืนยันตัวตน'}<br>ไม่เปิดพอร์ต Wi-Fi บ้านเพื่อให้คนนอกเชื่อมต่อ ESP32 โดยตรง</div><div style="margin-top:16px;display:flex;flex-wrap:wrap;gap:9px">${btn('เพิ่มบ้านอีกหลัง','new-home','plus','alt')}${btn('เข้าร่วมบ้าน','join-home','users','outline')}</div></div></div>${state.demo?`<button class="btn danger" data-act="reset-demo">ล้างข้อมูลตัวอย่าง</button>`:''}${isOwner()?`<div class="section-space"><button class="btn danger" data-act="remove-home">${icon('trash',16)} ลบบ้านนี้</button></div>`:''}`}
function renderDetail(){const d=dev(state.detailId);if(!d)return empty('ไม่พบอุปกรณ์','กลับไปหน้าอุปกรณ์');const row=state.history||[];
 return `<div class="headline-row"><div><button class="text-link" data-page="devices">← อุปกรณ์ทั้งหมด</button><h2>${safe(d.name)}</h2><p>${safe(labelType[d.kind])} · ${safe(roomName(d.room_id))}</p></div><div style="display:flex;gap:8px">${canManage()?btn('แก้ไข','edit-device','edit','alt'):''}${canManage()?`<button class="btn danger" data-act="remove-device" data-id="${safe(d.id)}">${icon('trash',16)} นำออก</button>`:''}</div></div>${d.kind==='energy_meter'?`<div class="stats">${stat('กำลังไฟปัจจุบัน',isOnline(d)?num(d.last_power_w,0):'—','W','bolt','','กำลังไฟที่ตู้เมน')}${stat('แรงดันไฟฟ้า',isOnline(d)?num(d.last_voltage_v):'—','V','chart','blue','แรงดันที่ PZEM วัดได้')}${stat('กระแสไฟฟ้า',isOnline(d)?num(d.last_current_a,2):'—','A','plug','purple','กระแสที่ PZEM วัดได้')}${stat('พลังงานสะสม',num(d.last_energy_kwh,3),'kWh','calendar','gold','พลังงานสะสมจากมิเตอร์')}</div>`:`<div class="panel section-space"><div class="panel-head"><h3>อุปกรณ์อัจฉริยะ</h3>${deviceStatus(d)}</div><p class="muted">อุปกรณ์นี้ไม่ใช้วัดไฟและไม่ถูกนับรวมในค่าไฟที่คำนวณจากตู้เมน</p></div>`}${d.kind==='energy_meter'?`<div class="two-cols">${historicalPanel('power')}<div class="panel"><div class="panel-head"><h3>ข้อมูลอุปกรณ์</h3></div><div class="list-rows"><div class="row-item"><strong>เฟิร์มแวร์</strong><span class="muted">${safe(d.firmware_version||'ไม่ทราบข้อมูล')}</span></div><div class="row-item"><strong>เชื่อมต่อครั้งล่าสุด</strong><span class="muted">${d.last_seen?new Date(d.last_seen).toLocaleString('th-TH'):'ไม่เคย'}</span></div><div class="row-item"><strong>ตัวประกอบกำลัง</strong><span class="muted">${num(d.last_pf,3)}</span></div><div class="row-item"><strong>ความถี่</strong><span class="muted">${num(d.last_frequency_hz)} Hz</span></div></div>${d.control_enabled?`<div class="section-space toggle-row"><span>เอาต์พุตควบคุมระยะไกล ${pending(d.id)?'(กำลังดำเนินการ)':''}</span><button class="switch-toggle ${d.relay_state?'on':''}" data-act="switch" data-id="${safe(d.id)}" ${!isOnline(d)||!canOperate()||pending(d.id)?'disabled':''}></button></div>`:''}</div></div>`:`<div class="panel section-space"><h3>ข้อมูลอุปกรณ์</h3><p class="muted">เฟิร์มแวร์: ${safe(d.firmware_version||'ไม่ทราบข้อมูล')} · ${deviceStatus(d)}</p>${d.control_enabled?`<div class="toggle-row"><span>สวิตช์ควบคุมระยะไกล ${pending(d.id)?'(กำลังดำเนินการ)':''}</span><button class="switch-toggle ${d.relay_state?'on':''}" data-act="switch" data-id="${safe(d.id)}" ${!isOnline(d)||!canOperate()||pending(d.id)?'disabled':''}></button></div>`:''}</div>`}`}
const navigation=[['overview','layout','ภาพรวม'],['devices','plug','อุปกรณ์ของฉัน'],['energy','chart','วิเคราะห์การใช้ไฟ'],['rooms','house','ห้อง'],['automations','clock','ระบบอัตโนมัติ'],['members','users','สมาชิก'],['notifications','bell','การแจ้งเตือน'],['settings','settings','ตั้งค่า']];
function renderShell(){let h=home();const unread=state.notifications.filter(x=>!x.read).length,initials=(state.user?.email||'DU').slice(0,2).toUpperCase();
 return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('home',22)}</span><div><b>Home Thames</b><small>SMART HOME</small></div></div><div><div class="nav-label">พื้นที่ใช้งาน</div><nav class="nav">${navigation.map(([k,ic,t])=>`<button data-page="${k}" class="${state.page===k||(k==='devices'&&state.page==='detail')?'active':''}">${icon(k==='overview'?'home':ic,19)} ${t}${k==='notifications'&&unread?`<span class="count">${unread}</span>`:''}</button>`).join('')}</nav></div><div class="nav-spacer"></div><div class="side-bottom"><span class="avatar">${safe(initials)}</span><div style="flex:1;min-width:0"><div class="user-name">${safe(state.user?.email||'Demo User')}</div><small>${state.demo?'โหมดตัวอย่าง':'เชื่อมต่อคลาวด์'}</small></div><button class="btn-ghost" data-act="logout" title="ออกจากระบบ">${icon('logout',17)}</button></div></aside>
 <main class="main"><header class="topbar"><div class="home-group"><span class="home-thumb">${icon('home',24)}</span><div><span class="eyebrow">บ้านอัจฉริยะของฉัน</span><div class="home-select">${icon('home',15)}<select id="home-picker" aria-label="Selected home">${state.homes.map(x=>`<option value="${safe(x.id)}" ${x.id===state.homeId?'selected':''}>${safe(x.name)}</option>`).join('')}</select>${icon('down',14)}</div></div></div><div class="top-right"><label class="global-search">${icon('search',18)}<input id="device-search" type="search" autocomplete="off" placeholder="ค้นหาอุปกรณ์…" aria-label="ค้นหาอุปกรณ์" value="${safe(state.deviceSearch)}"></label>${canManage()?btn('เพิ่มอุปกรณ์','add-device','plus','header-add'):''}<button class="icon-btn" data-page="notifications" title="การแจ้งเตือน">${icon('bell',19)}${unread?'<span class="bell-dot"></span>':''}</button><button class="icon-btn top-refresh" data-act="refresh" title="รีเฟรช">${icon('refresh',19)}</button><span class="top-avatar">${safe(initials)}</span></div></header>
 ${state.demo?'<div class="demo-banner"><span><strong>โหมดสาธิต</strong> · ข้อมูลตัวอย่างสำหรับทดลองหน้าตาและการควบคุม ไม่ใช่อุปกรณ์จริง</span><button data-act="cloud-guide">เชื่อมต่อคลาวด์ →</button></div>':''}
 ${state.busy?'<div class="pill" style="margin-bottom:10px">กำลังบันทึกข้อมูล...</div>':''}
 ${state.page==='overview'?renderOverview():state.page==='devices'?renderDevices():state.page==='energy'?renderEnergy():state.page==='rooms'?renderRooms():state.page==='automations'?renderAutomations():state.page==='members'?renderMembers():state.page==='notifications'?renderNotifications():state.page==='settings'?renderSettings():renderDetail()}
 </main></div><nav class="mobile-nav">${[['overview','home','หน้าแรก'],['devices','plug','อุปกรณ์'],['energy','chart','พลังงาน'],['rooms','house','ห้อง'],['settings','settings','เพิ่มเติม']].map(([k,ic,t])=>`<button class="${state.page===k?'active':''}" data-page="${k}">${icon(ic,21)}${t}</button>`).join('')}</nav>`;
}
function renderAuth(){return `<div class="auth-page"><section class="auth-promo"><div class="brand"><span class="brand-mark">${icon('bolt',22)}</span><div><b>Home Thames</b><small>SMART HOME</small></div></div><h1>บ้านของคุณ<br> <em>ฉลาดขึ้น</em> จากทุกที่</h1><p>จัดการบ้านหลายหลัง ตรวจสอบการใช้พลังงาน สั่งงานและสร้างระบบอัตโนมัติจากโทรศัพท์ได้ทุกที่</p><div class="auth-features"><div>${icon('shield',21)} เข้าระบบคลาวด์และจับคู่อุปกรณ์อย่างปลอดภัย</div><div>${icon('bolt',21)} ดูพลังงานและค่าไฟประมาณการได้ทุกที่</div><div>${icon('clock',21)} ตั้งเวลาและระบบอัตโนมัติ</div></div></section><section class="auth-form-wrap"><div class="auth-card"><span class="eyebrow">เริ่มต้นใช้งานบ้านอัจฉริยะ</span><h2>${state.authMode==='login'?'ยินดีต้อนรับกลับ':'สร้างบัญชีใหม่'}</h2><p>${state.authMode==='login'?'เข้าสู่ระบบบ้านอัจฉริยะของคุณ':'เริ่มต้นสร้างพื้นที่บ้านส่วนตัวที่ปลอดภัย'}</p><form class="form" data-form="auth"><div class="field"><label>อีเมล</label><input name="email" type="email" autocomplete="email" required placeholder="your@email.com"></div><div class="field"><label>รหัสผ่าน</label><input name="password" type="password" autocomplete="${state.authMode==='login'?'current-password':'new-password'}" minlength="8" required placeholder="อย่างน้อย 8 ตัวอักษร"></div><button class="btn full" type="submit">${state.authMode==='login'?'เข้าสู่ระบบ':'สมัครสมาชิก'} ${icon('arrow',16)}</button></form><div class="auth-switch">${state.authMode==='login'?`ยังไม่มีบัญชีใช่ไหม? <button data-act="auth-signup">สร้างบัญชีใหม่</button>`:`มีบัญชีอยู่แล้ว? <button data-act="auth-login">เข้าสู่ระบบ</button>`}</div><div class="divider-text">หรือ</div><button class="btn full alt" data-act="demo-mode">ทดลองระบบด้วยข้อมูลตัวอย่าง</button></div></section></div>`}
function formField(name,label,value='',type='text',extra=''){return `<div class="field"><label for="f-${safe(name)}">${label}</label><input id="f-${safe(name)}" name="${safe(name)}" type="${type}" value="${safe(value)}" ${extra}></div>`}
function selectField(name,label,options,selected=''){return `<div class="field"><label for="f-${safe(name)}">${label}</label><select id="f-${safe(name)}" name="${safe(name)}">${options.map(([id,t])=>`<option value="${safe(id)}" ${String(id)===String(selected)?'selected':''}>${safe(t)}</option>`).join('')}</select></div>`}
function renderPairWizard(){const m=state.modal;if(!m||m.type!=='pair-wizard')return '';
 const steps=['อุปกรณ์','เชื่อมต่อ','Wi-Fi บ้าน','จับคู่และตั้งชื่อ','เสร็จสิ้น'];const step=m.step||0;
 const radio=(kind,label,desc,ic)=>`<button type="button" class="pair-device-choice ${m.kind===kind?'chosen':''}" data-act="wizard-kind" data-id="${kind}"><span class="pair-choice-icon">${icon(ic,27)}</span><span><strong>${label}</strong><small>${desc}</small></span><span class="pair-radio">${m.kind===kind?icon('check',14):''}</span></button>`;
 let content='';
 if(step===0)content=`<div class="pair-intro"><h4>ต้องการเพิ่มอุปกรณ์ชนิดใด?</h4><p>เลือกประเภท ESP32 ที่ต้องการเชื่อมต่อกับบ้านนี้</p></div><div class="pair-choice-grid">${radio('energy_meter','มิเตอร์ไฟฟ้าหลัก','PZEM-004T · วัดที่ตู้เมน · บ้านละ 1 ตัว','bolt')}${radio('smart_switch','สวิตช์อัจฉริยะ','เปิด–ปิดจากระยะไกล · ต้องมีวงจรควบคุมที่ปลอดภัย','plug')}${radio('sensor','เซนเซอร์อัจฉริยะ','อ่านค่าจากเซนเซอร์','thermometer')}</div>${m.kind==='energy_meter'&&mainMeter()?'<div class="pair-warning">บ้านนี้มีมิเตอร์ไฟฟ้าหลักแล้ว โปรดเลือกประเภทอื่นหรือลบมิเตอร์เก่าก่อน</div>':''}`;
 if(step===1)content=`<div class="pair-intro"><span class="pair-big-ic">${icon('wifi',42)}</span><h4>เชื่อมต่อ ESP32</h4><p>เปิดบอร์ดในโหมดตั้งค่า จากนั้นเปิดการตั้งค่า Wi-Fi ของมือถือหรือคอมพิวเตอร์ แล้วเชื่อมต่อเครือข่ายชั่วคราวของบอร์ด</p></div><div class="pair-network"><span>${icon('wifi',19)}</span><div><strong>HomeThames-Setup-XXXX</strong><small>เครือข่าย Wi-Fi ชั่วคราวที่ ESP32 ปล่อยออกมา</small></div><span class="tag">2.4 GHz</span></div><div class="helper-box"><b>รหัสอนุญาตติดตั้ง (อายุ 15 นาที)</b><div class="code" style="overflow-wrap:anywhere;user-select:all">${safe(m.enrollmentTicket||"รอสั่งสร้างรหัส")}</div><button type="button" class="btn alt" data-act="copy-enrollment">คัดลอกรหัสติดตั้ง</button><p class="muted small">นำรหัสไปใส่หน้า Wi-Fi Setup ของ ESP32 ห้ามเผยแพร่แก่คนอื่น</p></div><div class="pair-steps-note"><p><b>1</b> แฟลชเฟิร์มแวร์ Home Thames และเปิด ESP32-C6</p><p><b>2</b> เปิด Serial Monitor 115200 เพื่อดูรหัสผ่าน Wi-Fi ตั้งค่าของบอร์ด</p><p><b>3</b> เชื่อมต่อ Wi-Fi Home Thames ด้วยมือถือหรือคอมพิวเตอร์ หากแจ้งว่า “ไม่มีอินเทอร์เน็ต” ให้เชื่อมต่อค้างไว้</p></div><div class="helper-box">เว็บไม่สามารถเปลี่ยนเครือข่าย Wi-Fi ของมือถือได้เองทุกเครื่อง ให้สลับ Wi-Fi ที่หน้าการตั้งค่าของอุปกรณ์</div>`;
 if(step===2)content=`<div class="pair-intro"><span class="pair-big-ic">${icon('router',42)}</span><h4>เลือก Wi-Fi บ้าน</h4><p>เปิดหน้าตั้งค่าของ ESP32 กดสแกน Wi-Fi เลือกเครือข่ายบ้าน 2.4 GHz แล้วใส่รหัสผ่านในหน้าของบอร์ด</p></div><div class="pair-network"><span>${icon('wifi',19)}</span><div><strong>หน้าตั้งค่า ESP32 ในเครือข่ายภายใน</strong><small>http://192.168.4.1 · เปิดได้เฉพาะตอนเชื่อม Wi-Fi ตั้งค่าของ ESP32</small></div></div><a class="btn full pair-open-link" href="http://192.168.4.1/" target="_blank" rel="noopener noreferrer">${icon('arrow',17)} เปิดหน้าตั้งค่า Wi-Fi ของ ESP32</a><div class="pair-steps-note"><p><b>1</b> เลือกชื่อ Wi-Fi บ้านจากรายการที่ ESP32 สแกนพบ</p><p><b>2</b> กรอกรหัสผ่าน Wi-Fi บ้าน <strong>ที่หน้า ESP32 โดยตรงเท่านั้น</strong></p><p><b>3</b> กรอกรหัสอนุญาตติดตั้ง 48 ตัวอักษรจากขั้นตอนก่อนหน้าที่หน้า ESP32 แล้วรอรหัสจับคู่ 16 ตัวอักษร</p></div><div class="helper-box">รหัสผ่าน Wi-Fi บ้านส่งตรงไปที่ ESP32 ไม่ส่งขึ้น Home Thames Cloud หากเปิดลิงก์ไม่ได้ ให้พิมพ์ <code>http://192.168.4.1</code> ในช่อง URL ขณะเชื่อม Wi-Fi ของบอร์ด</div>`;
 if(step===3)content=`<div class="pair-intro"><span class="pair-big-ic">${icon('check',39)}</span><h4>จับคู่อุปกรณ์กับ Home Thames</h4><p>กลับมาเชื่อมต่ออินเทอร์เน็ตปกติ แล้วกรอกรหัสจับคู่ใช้ครั้งเดียวที่หน้าตั้งค่า ESP32 แสดง</p></div><form class="form" id="wizard-claim-form" data-form="wizard-claim"><div class="field"><label for="pair-code">รหัสจับคู่ 16 ตัวอักษร</label><input id="pair-code" name="pairing_code" type="text" required minlength="16" maxlength="16" pattern="[0-9A-Fa-f]{16}" autocomplete="off" placeholder="AB12CD34EF56AB78" style="font-family:monospace;letter-spacing:1.4px;text-transform:uppercase"></div>${formField('name','ชื่ออุปกรณ์',m.kind==='energy_meter'?'มิเตอร์ไฟฟ้าหลัก':m.kind==='sensor'?'เซนเซอร์ของฉัน':'สวิตช์อัจฉริยะ','text','required maxlength="80"')}${m.kind==='energy_meter'?'<div class="helper-box">มิเตอร์หลักใช้วัดไฟฟ้ารวมทั้งบ้านเท่านั้น ไม่สามารถสั่งตัดไฟเมน</div>':selectField('room_id','ห้อง',[['','ไม่ระบุห้อง'],...state.rooms.map(r=>[r.id,r.name])])}<button type="submit" class="btn full">${icon('link',16)} ยืนยันจับคู่อุปกรณ์กับคลาวด์</button></form><div class="helper-box">รหัสจับคู่มีอายุ 30 นาที โหมดสาธิตสามารถใช้รหัสตัวอย่าง ABCD1234ABCD5678 ได้ ส่วนโหมดคลาวด์ต้องใช้รหัสที่เฟิร์มแวร์สร้างจริง</div>`;
 if(step===4)content=`<div class="pair-finished"><span>${icon('check',44)}</span><h4>เพิ่มอุปกรณ์สำเร็จ!</h4><p>${safe(m.pairedName||'อุปกรณ์ของคุณ')} ถูกเพิ่มเข้าบ้าน ${safe(home()?.name||'บ้านของคุณ')} แล้ว</p><div class="helper-box">${state.demo?'นี่เป็นอุปกรณ์ในโหมดสาธิต ไม่ได้ควบคุมอุปกรณ์จริง':'อุปกรณ์จะแสดงออนไลน์เมื่อส่งข้อมูลถึง Cloud สำเร็จ'}</div></div>`;
 return `<div class="modal-cover" data-act="close-modal"><div class="modal pair-modal" role="dialog" aria-modal="true" aria-label="เพิ่มอุปกรณ์"><div class="modal-head"><div><small class="eyebrow">Home Thames · เพิ่มอุปกรณ์</small><h3>เพิ่มอุปกรณ์ใหม่</h3></div><button type="button" class="btn-ghost" data-act="close-modal" aria-label="ปิด">${icon('x',21)}</button></div><div class="pair-progress">${steps.map((t,i)=>`<div class="pair-progress-step ${i===step?'current':''} ${i<step?'complete':''}"><span>${i<step?icon('check',13):i+1}</span><small>${t}</small></div>`).join('')}</div><div class="pair-content">${content}</div><div class="pair-footer">${step>0&&step<4?`<button class="btn outline" data-act="wizard-back">${icon('arrow-left',16)} ย้อนกลับ</button>`:'<span></span>'}${step===3?'':step===4?`<button class="btn" data-act="wizard-finish">ดูอุปกรณ์ ${icon('arrow',16)}</button>`:`<button class="btn" data-act="wizard-next" ${step===0&&m.kind==='energy_meter'&&mainMeter()?'disabled':''}>${step===0?'ถัดไป':step===1?'เชื่อมต่อ Wi-Fi ของบอร์ดแล้ว':'ไปขั้นตอนจับคู่'} ${icon('arrow',16)}</button>`}</div></div></div>`;
}
function renderModal(){if(state.modal?.type==='pair-wizard')return renderPairWizard();if(!state.modal)return '';const m=state.modal;let content='',title='',tip='';let submit='บันทึกการเปลี่ยนแปลง';const roomOptions=[['','ไม่ระบุห้อง'],...state.rooms.map(x=>[x.id,x.name])];
 if(m.type==='new-home'){title='เพิ่มบ้านใหม่';submit='สร้างบ้าน';content=formField('name','ชื่อบ้าน','','text','required maxlength="100"');tip='สร้างบ้านใหม่ได้หลายหลัง สมาชิกและอุปกรณ์จะแยกจากกัน'}
 if(m.type==='new-room'){title='เพิ่มห้องใหม่';submit='สร้างห้อง';content=formField('name','ชื่อห้อง','','text','required maxlength="80"')}
 if(m.type==='add-device'){title='จับคู่ ESP32 ตัวใหม่';submit='จับคู่อุปกรณ์';content=`<div class="helper-box">เชื่อมต่อ ESP32 ผ่าน Setup Wi-Fi และดูรหัสจับคู่ 16 ตัวอักษรที่ Serial Monitor หรือหน้า Setup ของบอร์ดก่อน</div>${formField('name','ชื่ออุปกรณ์','ESP32 ของฉัน','text','required maxlength="80"')}${state.demo?selectField('device_type','ประเภทอุปกรณ์ (โหมดสาธิต)',[['smart_switch','สวิตช์อัจฉริยะ'],['sensor','เซนเซอร์'],['energy_meter','มิเตอร์หลัก (บ้านละไม่เกิน 1 ตัว)']]):''}${formField('pairing_code','รหัสจับคู่','','text','required minlength="16" maxlength="16" pattern="[0-9A-Fa-f]{16}" autocomplete="off"')}${selectField('room_id','เลือกห้อง',roomOptions)}`;tip=state.demo?'Demo: ใส่รหัสใดก็ได้ 16 ตัวเพื่อจำลองการจับคู่':'Pairing code ใช้ครั้งเดียวและหมดอายุใน 30 นาที'}
 if(m.type==='edit-device'){const d=dev(state.detailId);if(!d)return '';title='แก้ไขอุปกรณ์';content=`${formField('name','ชื่ออุปกรณ์',d.name,'text','required maxlength="80"')}${selectField('room_id','เลือกห้อง',roomOptions,d.room_id||'')}`}
 if(m.type==='settings-billing'){let h=home();title='ตั้งค่าบ้านและค่าไฟ';content=`${formField('name','ชื่อบ้าน',h?.name,'text','required maxlength="100"')}${selectField('timezone','เขตเวลา',[['Asia/Bangkok','Asia/Bangkok'],['UTC','UTC'],['Asia/Singapore','Asia/Singapore'],['Europe/London','Europe/London'],['America/New_York','America/New_York']],h?.timezone)}<div class="form-grid">${formField('rate_per_kwh','ค่าไฟต่อหน่วย (บาท)',h?.rate_per_kwh,'number','required min="0" step="0.01"')}${formField('service_fee','ค่าบริการรายเดือน (บาท)',h?.service_fee,'number','required min="0" step="0.01"')}</div><div class="helper-box">มิเตอร์ไฟฟ้าหลัก เลือกให้อัตโนมัติจากอุปกรณ์วัดไฟ 1 ตัวที่ตู้เมนของบ้าน ไม่จำเป็นต้องเลือกมิเตอร์ย่อย</div>`}
 if(m.type==='new-rule'){title='สร้างกฎอัตโนมัติ';submit='สร้างกฎ';const triggers=[['daily_time','ตั้งเวลาทุกวัน'],['power_above','กำลังไฟเกินค่าที่กำหนด'],['power_below','กำลังไฟต่ำกว่าค่าที่กำหนด'],['offline','อุปกรณ์ออฟไลน์']];const controls=state.devices.filter(x=>x.control_enabled&&x.kind!=='energy_meter');content=`${formField('name','ชื่อกฎ','','text','required maxlength="100"')}${selectField('trigger_type','เงื่อนไข',triggers)}${selectField('trigger_device_id','อุปกรณ์ตรวจจับ',state.devices.filter(d=>d.kind==='energy_meter'||d.kind==='sensor').map(d=>[d.id,d.name]))}<div class="form-grid">${formField('threshold_w','เกณฑ์กำลังไฟ (วัตต์)','1000','number','min="0" step="1"')}${formField('time_local','เวลาภายในบ้าน','18:00','time')}</div>${selectField('target_device_id','อุปกรณ์ที่ควบคุม',controls.map(d=>[d.id,d.name]))}${selectField('desired_state','การทำงาน',[['true','สั่งเปิด'],['false','สั่งปิด']])}`;tip=controls.length?'Automation ที่ตั้งเวลาต้องเปิด Cron บน Cloud เพื่อให้ทำงานจริง':'ต้องมี สวิตช์อัจฉริยะ ออนไลน์ที่รองรับการควบคุมก่อนสร้าง Rule'}
 if(m.type==='new-invite'){title='เชิญสมาชิก';submit='สร้างรหัสเชิญ';content=selectField('role','สิทธิ์',[['member','สมาชิก (ควบคุมได้)'],['viewer','ผู้ชม (ดูข้อมูลอย่างเดียว)'],['admin','ผู้ดูแล (จัดการอุปกรณ์)']]);tip='สร้างโค้ดเชิญใช้ครั้งเดียว อายุ 24 ชั่วโมง'}
 if(m.type==='invite-result'){title='แชร์รหัสเชิญ';submit='ปิด';content=`<div class="helper-box">ส่งโค้ดนี้ให้สมาชิกผ่านช่องทางปลอดภัย หลังเข้าสู่ระบบให้เลือก เข้าร่วมบ้าน<br><div style="font-size:13px;margin-top:11px;overflow-wrap:anywhere"><span class="code" id="invite-code">${safe(m.code)}</span></div></div><button type="button" class="btn alt" data-act="copy-invite">${icon('copy',16)} คัดลอกรหัส</button>`}
 if(m.type==='join-home'){title='เข้าร่วมบ้าน';submit='เข้าร่วมบ้าน';content=formField('code','รหัสเชิญ','','text','required minlength="12"');tip='ขอรหัสจากเจ้าของบ้านแล้วนำมาใส่ที่นี่'}
 if(m.type==='cloud-guide'){title='เชื่อมต่อคลาวด์จริง';submit='ปิด';content=`<div class="helper-box">1. สร้าง Supabase Project<br>2. รัน SQL Migration ในโฟลเดอร์ <span class="code">supabase/migrations</span><br>3. Deploy Edge Functions<br>4. ใส่ <b>SUPABASE_URL</b> และ <b>SUPABASE_ANON_KEY</b> ใน <span class="code">config.js</span><br>5. เปิดเว็บใหม่ แล้ว Sign Up<br><br>อ่านคู่มือ <span class="code">README.md</span> และ <span class="code">DEPLOYMENT.md</span> ก่อนติดตั้งอุปกรณ์จริง</div>`}
 return `<div class="modal-cover" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-head"><h3>${safe(title)}</h3><button type="button" class="btn-ghost" data-act="close-modal" aria-label="ปิด">${icon('x',21)}</button></div><form class="form" data-form="${safe(m.type)}">${content}${tip?`<div class="muted small">${tip}</div>`:''}<div class="modal-footer"><button class="btn outline" type="button" data-act="close-modal">ยกเลิก</button><button class="btn" type="submit" ${m.type==='new-rule'&&!state.devices.some(x=>x.control_enabled)?'disabled':''}>${safe(submit)}</button></div></form></div></div>`;
}
function render(){let markup=state.user||state.demo?renderShell():renderAuth();$('#app').innerHTML=markup+renderModal()+'<div id="toasts" class="toast-wrap" aria-live="polite"></div>'}
async function loadHome(){if(!state.homeId){state.rooms=[];state.devices=[];state.automations=[];state.members=[];state.notifications=[];state.commands=[];state.dashboard=null;return}
 const a=api();const [rooms,devices,automations,members,notifications,commands,dashboard]=await Promise.all([
  a.getRooms(state.homeId),a.getDevices(state.homeId),a.getAutomations(state.homeId),a.getMembers(state.homeId),a.getNotifications(state.homeId),a.getCommands(state.homeId),a.getDashboard(state.homeId)]);
 Object.assign(state,{rooms,devices,automations,members,notifications,commands,dashboard});
 await loadTrends();
}
async function refresh(reloadHomes=false){try{
 if(reloadHomes||!state.homes.length){state.homes=await api().getHomes();if(!state.homes.some(h=>h.id===state.homeId))state.homeId=state.homes[0]?.id||null;}
 if(!state.homeId){state.modal={type:'new-home'};render();return;}
 await loadHome();render();
 }catch(e){render();showToast(e.message,true)}}
async function go(page){state.page=page;state.modal=null;if(page==='detail')state.history=[];await loadTrends();render();}
async function busy(action){if(state.busy)return;state.busy=true;try{await action();state.busy=false;await refresh(true)}catch(e){state.busy=false;render();showToast(e.message||String(e),true)}}
async function onAction(act,id){
 if(act==='close-modal'){state.modal=null;render();return;}
 if(act==='wizard-kind'){state.modal.kind=id;state.modal.enrollmentTicket=null;render();return;}
 if(act==='copy-enrollment'){
   try{await navigator.clipboard.writeText(state.modal?.enrollmentTicket||'');showToast('คัดลอกรหัสติดตั้งแล้ว')}
   catch{showToast('กรุณาเลือกข้อความและคัดลอกรหัสด้วยตนเอง',true)}
   return;
 }
 if(act==='wizard-next'){
  const m=state.modal;
  if((m.step||0)===0&&!m.enrollmentTicket){
   try{m.enrollmentTicket=state.demo?'DEMO48CHARACTERS_NOT_FOR_REAL_PAIRING':await cloud.createEnrollment(state.homeId,m.kind)}
   catch(e){showToast('สร้างรหัสติดตั้งไม่ได้: '+(e.message||e),true);return}
  }
  m.step=Math.min(3,(m.step||0)+1);render();return;
 }
 if(act==='wizard-back'){state.modal.step=Math.max(0,state.modal.step-1);render();return;}
 if(act==='wizard-finish'){state.modal=null;state.page='devices';await refresh();return;}
 if(act==='energy-period'&&PERIODS.includes(id)){state.energyPeriod=id;state.energyAnchor=todayAtHome();await loadTrends();render();return;}
 if(act==='energy-prev'||act==='energy-next'){state.energyAnchor=shiftPeriod(state.energyPeriod,state.energyAnchor,act==='energy-prev'?-1:1);await loadTrends();render();return;}
 if(act==='bill-prev'||act==='bill-next'){state.billMonth=shiftMonth(state.billMonth,act==='bill-prev'?-1:1);await loadTrends();render();return;}
 if(act==='room-filter'){state.roomFilter=id;render();return;}
 if(act==='auth-login'||act==='auth-signup'){state.authMode=act==='auth-login'?'login':'signup';render();return;}
 if(act==='demo-mode'){state.demo=true;state.user={id:'demo-user',email:'demo@homethames.local'};await refresh(true);return;}
 if(act==='cloud-guide'){state.modal={type:'cloud-guide'};render();return;}
 if(act==='logout'){await logout();state.user=null;state.demo=false;state.homes=[];state.homeId=null;state.modal=null;render();return;}
 if(act==='refresh'){await refresh(true);return;}
 if(act==='add-device'){state.modal={type:'pair-wizard',step:0,kind:mainMeter()?'smart_switch':'energy_meter'};render();return;}
 if(['new-home','new-room','new-rule','new-invite','join-home','settings-billing'].includes(act)){state.modal={type:act};render();return;}
 if(act==='edit-device'){state.modal={type:'edit-device'};render();return;}
 if(act==='detail'){state.detailId=id;state.page='detail';await refresh();return;}
 if(act==='switch'){const d=dev(id);if(!d||d.kind==='energy_meter'||!d.control_enabled||!isOnline(d)||!canOperate())return;await busy(async()=>{await api().command(state.homeId,id,!d.relay_state)});return;}
 if(act==='toggle-rule'){const a=state.automations.find(x=>x.id===id);if(a)await busy(()=>api().updateAutomation(id,{enabled:!a.enabled}));return;}
 if(act==='remove-rule'){if(confirm('ต้องการลบกฎอัตโนมัตินี้หรือไม่?'))await busy(()=>api().removeAutomation(id));return;}
 if(act==='remove-device'){if(confirm('ต้องการลบอุปกรณ์และยกเลิกรหัสใช้งานหรือไม่? ข้อมูลย้อนหลังจะถูกลบด้วย'))await busy(async()=>{await api().removeDevice(id);state.page='devices'});return;}
 if(act==='remove-member'){if(isOwner()&&confirm('ต้องการนำสมาชิกคนนี้ออกจากบ้านหรือไม่?'))await busy(()=>api().removeMember(state.homeId,id));return;}
 if(act==='remove-home'){if(isOwner()&&confirm('ต้องการลบบ้านและข้อมูลทั้งหมดอย่างถาวรหรือไม่? การดำเนินการนี้ย้อนกลับไม่ได้'))await busy(async()=>{await api().removeHome(state.homeId);state.homeId=null;state.page='overview'});return;}
 if(act==='remove-room'){if(confirm('ต้องการลบห้องหรือไม่? อุปกรณ์ในห้องจะเปลี่ยนเป็นไม่ระบุห้อง'))await busy(()=>api().removeRoom(id));return;}
 if(act==='read-note'){await busy(()=>api().readNotification(id));return;}
 if(act==='copy-invite'){const code=state.modal?.code||'';try{await navigator.clipboard.writeText(code);showToast('คัดลอกรหัสเชิญแล้ว')}catch{showToast('กรุณาเลือกและคัดลอกรหัสด้วยตนเอง',true)}return;}
 if(act==='reset-demo'){if(confirm('ต้องการคืนค่าข้อมูลตัวอย่างทั้งหมดหรือไม่?')){resetDemo();state.page='overview';await refresh(true)}return;}
}
async function onForm(type,form){const v=Object.fromEntries(new FormData(form).entries());
 if(type==='auth'){
  try{if(state.authMode==='login')state.user=await login(String(v.email),String(v.password));else{
   const result=await signup(String(v.email),String(v.password),String(v.email).split('@')[0]);
   if(!result.access_token){showToast('กรุณาตรวจอีเมลเพื่อยืนยันการสมัคร แล้วเข้าสู่ระบบ');state.authMode='login';render();return;}
   state.user=currentUser();}
   state.demo=false;await refresh(true);
  }catch(e){showToast(e.message,true)}return;
 }
 if(type==='invite-result'||type==='cloud-guide'){state.modal=null;render();return;}
 if(type==='wizard-claim'){const m=state.modal;if(!m||m.type!=='pair-wizard')return;try{const a=api(),name=String(v.name||'').trim();await a.claimDevice({home_id:state.homeId,room_id:v.room_id||null,name,pairing_code:String(v.pairing_code||'').trim().toUpperCase(),kind:m.kind});await loadHome();state.modal={type:'pair-wizard',step:4,kind:m.kind,pairedName:name};render();}catch(err){showToast(err.message||String(err),true);}return;}
 await busy(async()=>{
  const a=api();
  switch(type){
   case 'new-home':state.homeId=await a.createHome(String(v.name).trim());break;
   case 'new-room':await a.createRoom(state.homeId,String(v.name).trim());break;
   case 'add-device':await a.claimDevice({home_id:state.homeId,room_id:v.room_id||null,name:String(v.name).trim(),pairing_code:String(v.pairing_code).trim().toUpperCase(),kind:v.device_type||undefined});break;
   case 'edit-device':await a.updateDevice(state.detailId,{name:String(v.name).trim(),room_id:v.room_id||null});break;
   case 'settings-billing':await a.updateHome(state.homeId,{name:String(v.name).trim(),timezone:v.timezone,rate_per_kwh:Number(v.rate_per_kwh),service_fee:Number(v.service_fee)});break;
   case 'new-rule':{
    const isTime=v.trigger_type==='daily_time',needsPower=['power_above','power_below'].includes(String(v.trigger_type));
    await a.addAutomation({home_id:state.homeId,name:String(v.name).trim(),trigger_type:v.trigger_type,
      trigger_device_id:isTime?null:v.trigger_device_id||null,
      time_local:isTime?v.time_local:null,threshold_w:needsPower?Number(v.threshold_w):null,
      target_device_id:v.target_device_id,desired_state:v.desired_state==='true',enabled:true});break;
   }
   case 'new-invite':{const code=await a.createInvite(state.homeId,String(v.role));state.modal={type:'invite-result',code};return;}
   case 'join-home':{state.homeId=await a.acceptInvite(String(v.code));break;}
  }
  if(type!=='new-invite')state.modal=null;
 });
 if(type==='new-invite'&&state.modal?.type==='invite-result')render();
}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-act],[data-page]');if(!el)return;
 if(el.classList.contains('modal-cover')&&e.target!==el)return;
 e.preventDefault();if(el.dataset.page){go(el.dataset.page);return;}
 await onAction(el.dataset.act,el.dataset.id);
});
document.addEventListener('input',e=>{if(e.target.id==='device-search'){state.deviceSearch=e.target.value;document.querySelectorAll('[data-search-name]').forEach(card=>{card.hidden=!card.dataset.searchName.includes(state.deviceSearch.toLowerCase().trim());});}});
document.addEventListener('keydown',e=>{if(e.target.id==='device-search'&&e.key==='Enter'){e.preventDefault();state.page='devices';render();const input=document.getElementById('device-search');input?.focus();input?.setSelectionRange(input.value.length,input.value.length);document.querySelectorAll('[data-search-name]').forEach(card=>{card.hidden=!card.dataset.searchName.includes(state.deviceSearch.toLowerCase().trim());});}});
document.addEventListener('change',async e=>{
 if(e.target.id==='home-picker'){state.homeId=e.target.value;state.roomFilter='all';state.page='overview';state.energySeriesKey='';state.billSeriesKey='';state.energySeries=[];state.billSeries=[];state.trendError='';state.energyAnchor=todayAtHome();state.billMonth=todayAtHome().slice(0,7);await refresh()}
 if(e.target.matches('[data-energy-date]')){state.energyAnchor=e.target.value;await loadTrends();render();}
 if(e.target.matches('[data-energy-month]')){state.energyAnchor=e.target.value+'-01';await loadTrends();render();}
 if(e.target.matches('[data-energy-year]')){state.energyAnchor=e.target.value+'-01-01';await loadTrends();render();}
 if(e.target.matches('[data-bill-month]')){state.billMonth=e.target.value;await loadTrends();render();}
});
document.addEventListener('submit',async e=>{
 const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();await onForm(f.dataset.form,f);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render()}});
async function init(){
 if(!configured()){state.demo=true;state.user={id:'demo-user',email:'demo@homethames.local'};await refresh(true);return;}
 state.user=currentUser();if(state.user)await refresh(true);else render();
}
init().catch(e=>{$('#app').innerHTML=`<div class="boot"><h2>ไม่สามารถเปิด Home Thames ได้</h2><p>${safe(e.message)}</p></div>`});
setInterval(()=>{if(state.homeId&&!state.modal&&!state.busy&&document.visibilityState==='visible')refresh().catch(()=>{})},15000);
if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
